package backend

const Endpoint = "GET /items"

func FetchItems(cursor string, limit int) string {
	if limit < 1 {
		return `{"items":[],"next_cursor":null}`
	}

	if cursor == "" || cursor == "null" {
		if limit == 1 {
			return `{"items":[{"id":"i1","name":"one"}],"next_cursor":"cursor-1"}`
		}
		if limit == 2 {
			return `{"items":[{"id":"i1","name":"one"},{"id":"i2","name":"two"}],"next_cursor":"cursor-2"}`
		}
		return `{"items":[{"id":"i1","name":"one"},{"id":"i2","name":"two"},{"id":"i3","name":"three"}],"next_cursor":null}`
	}

	if cursor == "cursor-1" {
		return `{"items":[{"id":"i2","name":"two"}],"next_cursor":"cursor-2"}`
	}

	if cursor == "cursor-2" {
		return `{"items":[{"id":"i3","name":"three"}],"next_cursor":null}`
	}

	return `{"items":[],"next_cursor":null}`
}
